//! Compiles the vendored Piton Tree-sitter parser, which has no Rust bindings,
//! the Piton prompts in `system-prompts`, which become constants in the
//! application (see `src/baked_prompts.rs`), and the new project templates in
//! `project-templates`, whose files are built in (see
//! `src/project_templates.rs`).

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::Path;
use std::process::Command;

use serde_json::{Map, Value};

/// Where the prompts are written.
const PROMPTS: &str = "system-prompts";

/// The prompts last compiled, kept with the source so the application still
/// builds where `piton` isn't installed, as on CI.
const SNAPSHOT: &str = "system-prompts/compiled.json";

fn main() {
    compile_parser();
    compile_prompts();
    embed_templates();
    bake_build_info();
}

/// Bakes in what About Suspense shows of the build (see `src/about.rs`): the
/// commit it was built from, as `SUSPENSE_COMMIT`, where git can say, and the
/// date it was built, as `SUSPENSE_BUILT`, from `SOURCE_DATE_EPOCH` where it
/// is set and the clock otherwise. Built again as the commit changes.
fn bake_build_info() {
    for watched in [".git/HEAD", ".git/refs/heads", ".git/packed-refs"] {
        if Path::new(watched).exists() {
            println!("cargo:rerun-if-changed={watched}");
        }
    }
    println!("cargo:rerun-if-env-changed=SOURCE_DATE_EPOCH");
    let commit = Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .ok()
        .filter(|output| output.status.success())
        .map(|output| String::from_utf8_lossy(&output.stdout).trim().to_string())
        .filter(|commit| !commit.is_empty());
    if let Some(commit) = commit {
        println!("cargo:rustc-env=SUSPENSE_COMMIT={commit}");
    }
    let seconds = std::env::var("SOURCE_DATE_EPOCH")
        .ok()
        .and_then(|epoch| epoch.parse::<u64>().ok())
        .or_else(|| {
            std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .ok()
                .map(|since| since.as_secs())
        });
    if let Some(seconds) = seconds {
        println!("cargo:rustc-env=SUSPENSE_BUILT={}", date(seconds));
    }

